INSERT INTO `certifications` VALUES (2,'Garantie décennale','Profitez de la tranquillité d’esprit grâce à notre garantie décennale sur tous nos travaux de toiture.','/assets/certifications/garantie-decennale.webp','Logo de la garantie décennale','https://www.april.fr/',1,1),(3,'Certifié RGE QUALIBAT','Assurez-vous des services de haute qualité, réalisés par des experts reconnus et certifiés RGE QUALIBAT.','/assets/certifications/rge-qualibat.webp','Logo de la certification RGE QUALIBAT',NULL,2,1),(4,'Installateur Conseil Expert VELUX','Aertoit est certifié « Installateur Conseil Expert VELUX » pour une installation professionnelle garantie.',NULL,'Logo Installateur Conseil Expert VELUX',NULL,3,1),(6,'Adhérent Fédération Française du Bâtiment','Informations réglementaires et techniques de la profession.',NULL,'Logo de la Fédération Française du Bâtiment','https://www.ffbatiment.fr/',4,1);
