LOCK TABLES `faqs` WRITE;
/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (1,'Pourquoi choisir la fibre de bois comme isolant pour ma toiture ?','La fibre de bois est un excellent isolant thermique et acoustique. Elle offre une grande capacité de déphasage thermique, c’est-à-dire qu’elle retarde le transfert de chaleur, ce qui permet de maintenir une température agréable à l’intérieur pendant les périodes de fortes chaleurs. De plus, la fibre de bois est un matériau écologique, durable et respectueux de l’environnement.','global',1,1),(2,'Quels sont les avantages des tuiles en tant que couverture pour la toiture ?','La tuile offre une excellente longévité, souvent supérieure à cinquante ans, pour un entretien limité. Elle résiste bien au gel et aux fortes pluies, se répare unité par unité sans toucher au reste de la couverture, et s’intègre naturellement au bâti francilien. Terre cuite ou béton, plate ou mécanique, le choix dépend de la pente de votre toit et des règles d’urbanisme de votre commune.','global',2,1),(3,'Est-il possible d’installer une fenêtre de toit VELUX sur un toit terrasse ?','Oui. Sur une toiture plate ou à très faible pente, on ne pose pas une fenêtre de toit classique mais une verrière plate ou une coupole VELUX conçue pour cet usage, montée sur une costière qui assure la reprise d’étanchéité. En tant qu’Installateur Conseil Expert VELUX, nous vérifions la compatibilité de votre support et réalisons les relevés d’étanchéité nécessaires.','global',3,1),(4,'Comment garantir l’étanchéité d’un toit terrasse ?','L’étanchéité repose sur trois points : un support sain et correctement pentu pour l’évacuation des eaux, un complexe d’étanchéité adapté à l’usage de la terrasse, et des relevés soignés en périphérie et autour de chaque émergence. Un contrôle visuel annuel et le nettoyage des évacuations suffisent ensuite à prévenir la grande majorité des infiltrations.','global',4,1),(5,'Combien de fois par an est-il recommandé de nettoyer ses gouttières et pourquoi est-ce important ?','Deux fois par an suffisent dans la plupart des cas : une fois à l’automne après la chute des feuilles, une fois au printemps. Une gouttière obstruée déborde et l’eau ruisselle le long de la façade, ce qui dégrade les enduits, sature les fondations et peut provoquer des infiltrations en pied de toiture. Un nettoyage régulier coûte bien moins cher que la reprise des dégâts qu’il évite.','global',5,1);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

