INSERT INTO `job_postings` VALUES (2,'couvreur-qualifie','Couvreur/euse Qualifié(e)','CDI','L’Haÿ-les-Roses (94)','Vous réalisez des travaux de couverture en tuile, ardoise et zinc sur des chantiers variés.','<p>21/10/2024</p><p>📍94240 Val-de-Marne</p><p>📄 CDD avec possibilité de CDI</p><p>🕐 Temps Plein</p><p>💸 1900 - 2400 € net / mois + primes</p><p>🎓 CAP / BP ou autres</p><p>💼 ≥ 5 ans</p><h2>Description du Poste</h2><p>Vous accompagnerez votre chef d’équipe pour la réalisation de travaux de couverture en neuf et en rénovation, incluant la pose de matériaux variés tels que tuiles, ardoises, zinc, bac acier, plomb, etc.</p><p>Si ce profil correspond au vôtre et que vous avez les compétences requises, postulez pour rejoindre notre équipe motivée.</p><h2>Les Missions</h2><ul><li>Gestion et supervision des chantiers</li><li>Relation client et reporting</li><li>Réalisation des travaux de couvertures</li><li>Gestion du matériel et de son équipe</li><li>Contrôle qualité, sécurité et conformité</li><li>Encadrer et former des équipes moins expérimentées</li></ul><h2>Profil Recherché</h2><h3>Qualités Personelles</h3><p>Autonomie et sens de l\'initiative</p><p>Précision et rigueur dans l\'exécution des tâches</p><p>Esprit d\'équipe et capacité à encadrer des équipes</p><h3>Compétences Techniques</h3><ul><li>Maîtrise des différentes techniques de couverture et des matériaux couramment utilisés</li><li>Connaissance approfondie des normes de sécurité liées au travail en hauteur</li><li>Capacité à lire et interpréter des plans et des croquis techniques</li></ul><h3>Avantages</h3><p>Mutuelle d\'entreprise</p><p>Participation aux frais de transport</p><p>Formations continues et possibilités d\'évolution</p><p>Primes individuelles semestrielles</p><p>Activités extraprofessionnelles (repas de fin d\'année, séminaires)</p><p>Accès à des places pour des événements sportifs (PSG Parc des Princes)</p><h3>Conditions de Travail</h3><p>Travail principalement en extérieur et en hauteur</p><p>Déplacements possibles sur différents chantiers</p><p>Port des équipements de protection individuelle obligatoire</p><p>Prêt à rejoindre une entreprise dynamique ?</p><h2>Nos attendons votre CV avec impatience !</h2><p>Démarrez votre candidature dès maintenant en remplissant le formulaire de recrutement</p>','Couvreur/euse Qualifié(e) (H/F) — Rejoignez Aertoit Couverture','Aertoit Couverture recrute un couvreur qualifié en CDI dans le Val-de-Marne. Envoyez votre CV dès maintenant.',2,1,'2026-08-04 16:46:55'),(3,'couvreur-experimente','Chef/fe d’équipe - Couvreur/euse Expérimenté(e)','CDI','L’Haÿ-les-Roses (94)','Vous intervenez en autonomie sur des chantiers de rénovation de toiture exigeants.','<p>06/08/2024</p><p>📍94240 Val-de-Marne</p><p>📄 CDI</p><p>🕐 Temps Plein</p><p>💸 2300 - 2900 € net / mois + primes</p><p>🎓 CAP / BP ou autres</p><p>💼 ≥ 10 ans</p><h2>Description du Poste</h2><p>Vous serez responsable de la réalisation de travaux de couverture en neuf et en rénovation, incluant la pose de matériaux variés tels que tuiles, ardoises, zinc, bac acier, plomb, etc.</p><p>Si ce profil correspond au vôtre et que vous avez les compétences requises, postulez pour rejoindre notre équipe motivée.</p><h2>Les Missions</h2><ul><li>Gestion et supervision des chantiers</li><li>Relation client et reporting</li><li>Réalisation des travaux de couvertures</li><li>Gestion du matériel et de son équipe</li><li>Contrôle qualité, sécurité et conformité</li><li>Encadrer et former des équipes moins expérimentées</li></ul><h2>Profil Recherché</h2><h3>Qualités Personelles</h3><p>Autonomie et sens de l\'initiative</p><p>Aptitude à planifier les travaux et à gérer les priorités avec précision</p><p>Esprit d\'équipe et capacité à encadrer des équipes (leadership)</p><p>Bon relationnel pour assurer une communication efficace avec l’équipe</p><p>et les clients.</p><h3>Compétences Techniques</h3><ul><li>Maîtrise des différentes techniques de couverture et des matériaux couramment utilisés</li><li>Connaissance approfondie des normes de sécurité liées au travail en hauteur</li><li>Capacité à lire et interpréter des plans et des croquis techniques</li></ul><h3>Avantages</h3><p>Mutuelle d\'entreprise</p><p>Participation aux frais de transport</p><p>Formations continues et possibilités d\'évolution</p><p>Primes individuelles semestrielles</p><p>Activités extraprofessionnelles (repas de fin d\'année, séminaires)</p><p>Accès à des places pour des événements sportifs (PSG Parc des Princes)</p><h3>Conditions de Travail</h3><p>Travail principalement en extérieur et en hauteur</p><p>Déplacements possibles sur différents chantiers</p><p>Port des équipements de protection individuelle obligatoire</p><p>Prêt à rejoindre une entreprise dynamique ?</p><h2>Nos attendons votre CV avec impatience !</h2><p>Démarrez votre candidature dès maintenant en remplissant le formulaire de recrutement</p>','Chef/fe d’équipe - Couvreur/euse Expérimenté(e) (H/F) — Aertoit Couverture','Aertoit Couverture recrute un couvreur expérimenté en CDI dans le Val-de-Marne. Envoyez votre CV dès maintenant.',1,1,'2026-08-04 16:46:55'),(4,'assistant-polyvalent','Assistant(e) Polyvalent(e)','CDI','L’Haÿ-les-Roses (94)','Vous assurez l’accueil, le suivi administratif des chantiers et la relation client.','<p>07/08/2024</p><p>📍94240 L\'Haÿ-les-Roses</p><p>📄 Alternance</p><p>🕐 Temps Plein</p><p>💸 2500 € / mois</p><p>🎓 BTS Gestion de la PME</p><p>💼 ≥ 1 an</p><h2>Description du Poste</h2><p>Vous serez responsable de la logistique administrative ainsi que du suivi client et de la gestion des équipes</p><p>Si ce profil correspond au vôtre et que vous avez les compétences requises, postulez pour rejoindre notre équipe motivée.</p><h2>Les Missions</h2><ul><li>Gestion et supervision des chantiers</li><li>Relation client et reporting</li><li>Réalisation des travaux de couvertures</li><li>Gestion du matériel et de son équipe</li><li>Contrôle qualité, sécurité et conformité</li><li>Encadrer et former des équipes moins expérimentées</li></ul><h2>Profil Recherché</h2><h3>Qualités Personelles</h3><p>Autonomie et sens de l\'initiative</p><p>Précision et rigueur dans l\'exécution des tâches</p><p>Esprit d\'équipe et capacité à encadrer des équipes</p><h3>Compétences Techniques</h3><ul><li>Maîtrise des différentes techniques de couverture et des matériaux couramment utilisés</li><li>Connaissance approfondie des normes de sécurité liées au travail en hauteur</li><li>Capacité à lire et interpréter des plans et des croquis techniques</li></ul><h3>Avantages</h3><p>Mutuelle d\'entreprise</p><p>Participation aux frais de transport</p><p>Formations continues et possibilités d\'évolution</p><p>Primes individuelles semestrielles</p><p>Activités extraprofessionnelles (repas de fin d\'année, séminaires)</p><p>Accès à des places pour des événements sportifs (PSG Parc des Princes)</p><h3>Conditions de Travail</h3><p>Prêt à rejoindre une entreprise dynamique ?</p><h2>Nos attendons votre CV avec impatience !</h2><p>Démarrez votre candidature dès maintenant en remplissant le formulaire de recrutement</p>','Assistant(e) Polyvalent(e) (H/F) — Rejoignez Aertoit Couverture','Aertoit Couverture recrute un assistant polyvalent en CDI dans le Val-de-Marne. Envoyez votre CV dès maintenant.',3,1,'2026-08-04 16:46:55');
