INSERT INTO `pages` VALUES (1,'a-propos','À Propos d\'Aertoit Couverture','Découvrez une équipe de professionnels de la toiture à votre service !','<h2>Qui sommes-nous ?</h2><p>Aertoit Couverture est votre partenaire de confiance pour tous vos besoins en toiture. Basés à L\'Haÿ-les-Roses, nous mettons notre expertise et notre passion au service de la protection et de la beauté de votre maison.</p>',NULL,NULL,'À propos d\'Aertoit Couverture — Couvreurs dans le Val-de-Marne','Découvrez Aertoit Couverture, votre expert en travaux de toiture, charpente, isolation et étanchéité. Une expertise française depuis 2005.',1,'2026-08-06 05:28:31','2026-08-11 15:17:32'),(3,'pourquoi-nous-choisir','Pourquoi Nous Choisir ?','Professionnels de la toiture, les équipes d’Aertoit Couverture portent une attention particulière à vous offrir une qualité irréprochable dans la réalisation de vos toitures. Nous mettons un point d’honneur à respecter les délais annoncés lors de l’établissement de votre devis.','<h3>Dépannage d’Urgence</h3><p>En cas d’urgence, nous mettons tout en œuvre pour mobiliser une équipe afin d’intervenir dans les plus brefs délais. Contactez-nous à tout moment pour une intervention rapide et efficace.</p><h3>Engagement Écologique</h3><h3>Couvreurs Qualifiés</h3><h3>Service d’Accueil</h3>',NULL,NULL,'Pourquoi choisir Aertoit Couverture','Dépannage d’urgence, engagement écologique, couvreurs qualifiés et service d’accueil : pourquoi confier votre toiture à Aertoit Couverture.',1,'2026-08-06 14:05:08','2026-08-17 07:53:21'),(4,'savoir-faire-francais','Savoir-faire français, 20 ans d\'expérience','Aertoit met en avant l\'excellence du savoir-faire local en travaillant avec des professionnels expérimentés. Nous assurons un travail de haute qualité en respectant rigoureusement les normes et en valorisant le patrimoine architectural français.',NULL,NULL,NULL,'Savoir-faire français','Aertoit met en avant l\'excellence du savoir-faire local en travaillant avec des professionnels expérimentés. Nous assurons un travail de haute qualité en respectant rigoureusement les normes et en valorisant le patrimoine architectural français.',1,'2026-08-06 22:01:03','2026-08-17 07:53:21');
