INSERT INTO `testimonials` VALUES (1,'Dragna T.','Client Aertoit','Merci à toute l’équipe Aertoit','Une véritable écoute et de bons conseils lors de l’offre de prix. Les travaux ont été réalisés sur la période définie, avec un grand professionnalisme et sans surprise tarifaire.',5,'https://g.co/kgs/dCcC2Bj',1,1,'2026-08-04 16:46:55'),(2,'Sébastien C.','Client Aertoit','Équipe compétente et rassurante','Très bon professionnalisme du responsable et de ses équipes. Prise en charge parfaite depuis la réalisation du devis jusqu’à la réception du chantier.',5,'https://g.co/kgs/7u2kFzt',2,1,'2026-08-04 16:46:55'),(3,'Vincent C.','Client Aertoit','Nous recommandons sans réserve','Délais annoncés tenus. Travaux de qualité. Chantier au propre chaque soir. Personnels de qualité, qui aiment leur métier, ponctuels, polis, très professionnels.',5,'https://g.co/kgs/VQ138dX',3,1,'2026-08-04 16:46:55'),(4,'Luc B.','Client Aertoit','Ponctuel, professionnel et à l’écoute','L’équipe d’Aertoit est parfaitement autonome et est à votre écoute pour vos demandes particulières. Aertoit fait du travail de professionnel extrêmement soigné.',5,'https://g.co/kgs/YSAAszk',4,1,'2026-08-04 16:46:55'),(5,'Jean-Pierre D.','Client Aertoit','Très bon rapport qualité / prix','Nous avons fait appel à la société Aertoit pour un remplacement de la partie zinc de notre toiture ainsi que le remplacement de toutes les gouttières et descentes d’eau.',5,'https://g.co/kgs/3bDKPDK',5,1,'2026-08-04 16:46:55'),(6,'Nina V.','Client Aertoit','Ravis de notre expérience avec Aertoit','Aertoit a compris les spécificités de nos problèmes de toiture et Velux et résolu une fuite dont l’origine n’était pas évidente. Artisans professionnels, propres et aimables.',5,'https://g.co/kgs/8UM6WvD',6,1,'2026-08-04 16:46:55');
